package backoff

import "time"

// Delay returns the exponential backoff delay for the given attempt
// (counting from 1): base * 2^(attempt-1), capped at max.
func Delay(attempt int, base, max time.Duration) time.Duration {
	if attempt < 1 || base <= 0 || max <= 0 {
		return 0
	}
	d := base
	for i := 1; i < attempt; i++ {
		if d >= max || d > max/2 {
			return max
		}
		d *= 2
	}
	if d > max {
		return max
	}
	return d
}

