package backoff

import (
	"math"
	"testing"
	"time"
)

func TestDelay(t *testing.T) {
	const maxDur = time.Duration(math.MaxInt64)
	tests := []struct {
		name    string
		attempt int
		base    time.Duration
		max     time.Duration
		want    time.Duration
	}{
		{"attempt 1", 1, time.Second, time.Minute, time.Second},
		{"attempt 2", 2, time.Second, time.Minute, 2 * time.Second},
		{"attempt 3", 3, time.Second, time.Minute, 4 * time.Second},
		{"attempt 6", 6, time.Second, time.Minute, 32 * time.Second},
		{"attempt 7 capped", 7, time.Second, time.Minute, time.Minute},
		{"exactly max", 7, time.Second, 64 * time.Second, 64 * time.Second},
		{"just under max", 6, time.Second, 63 * time.Second, 32 * time.Second},
		{"next doubling passes max", 7, time.Second, 63 * time.Second, 63 * time.Second},
		{"attempt 0", 0, time.Second, time.Minute, 0},
		{"negative attempt", -5, time.Second, time.Minute, 0},
		{"zero base", 3, 0, time.Minute, 0},
		{"negative base", 3, -time.Second, time.Minute, 0},
		{"zero max", 3, time.Second, 0, 0},
		{"negative max", 3, time.Second, -time.Minute, 0},
		{"base above max", 1, time.Minute, time.Second, time.Second},
		{"base above max later attempt", 4, time.Minute, time.Second, time.Second},
		{"attempt 63", 63, time.Second, time.Hour, time.Hour},
		{"attempt 64", 64, time.Second, time.Hour, time.Hour},
		{"attempt 65", 65, time.Second, time.Hour, time.Hour},
		{"attempt 200", 200, time.Second, time.Hour, time.Hour},
		{"max int attempt", math.MaxInt, time.Second, time.Hour, time.Hour},
		{"huge max, large attempt", 200, time.Nanosecond, maxDur, maxDur},
		{"huge max, doubling near overflow", 63, time.Nanosecond, maxDur, maxDur},
		{"huge max, last exact doubling", 63, time.Nanosecond, maxDur, maxDur},
		{"huge base", 2, maxDur / 2 + 1, maxDur, maxDur},
		{"huge base and max, attempt 1", 1, maxDur, maxDur, maxDur},
		{"1ns base", 10, time.Nanosecond, time.Hour, 512 * time.Nanosecond},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Delay(tt.attempt, tt.base, tt.max); got != tt.want {
				t.Errorf("Delay(%d, %v, %v) = %v, want %v", tt.attempt, tt.base, tt.max, got, tt.want)
			}
		})
	}
}

func TestDelayMonotonicAndBounded(t *testing.T) {
	base, max := 100*time.Millisecond, 30*time.Second
	prev := time.Duration(0)
	for a := 1; a <= 300; a++ {
		got := Delay(a, base, max)
		if got < prev {
			t.Fatalf("attempt %d: delay %v decreased from %v", a, got, prev)
		}
		if got <= 0 || got > max {
			t.Fatalf("attempt %d: delay %v out of range (0, %v]", a, got, max)
		}
		prev = got
	}
	if prev != max {
		t.Errorf("final delay = %v, want %v", prev, max)
	}
}

